@push('scripts')<script>$(function(){var t=$('#asset-import-batches'),x=$.fn.dataTable.render.text(),labels={DRAFT:'ร่าง',VALIDATED:'ตรวจสอบแล้ว',COMMITTED:'นำเข้าแล้ว'},classes={DRAFT:'app-badge-soft',VALIDATED:'app-badge-info',COMMITTED:'app-badge-success'};t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:t.data('url'),order:[[1,'desc']],buttons:[window.erpExcelButton(t)],columns:[{data:'batch_reference',render:x.display},{data:'cutover_date',render:x.display},{data:'status',render:function(v,z){return z==='display'?'<span class="badge '+(classes[v]||'app-status-neutral')+'">'+x.display(labels[v]||v)+'</span>':v;}},{data:'lines_count',className:'text-end',render:x.display},{data:'total_opening_cost',className:'text-end',render:function(v,z){return z==='display'?Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}):v;}},{data:'show_url',orderable:false,searchable:false,className:'text-end',render:function(v,z){return z==='display'?'<a class="btn btn-sm btn-outline-dark" href="'+x.display(v)+'">ดูรายละเอียด</a>':'';}}]}));});</script>@endpush
